import csv, numpy as np, math
from scipy.optimize import minimize
rows=list(csv.DictReader(open('/scr/wurgaft/auto-psych/agent_trees/80aefb383357367b/repo/_runs/cell_1/experiment2/model_loop/responses.csv')))
P=set(n for n in range(2,101) if all(n%d for d in range(2,int(n**.5)+1)))
def props(n):
    p={"even" if n%2==0 else "odd", f"last{n%10}", f"dec{min(n//10,9)}"}
    p|={f"has{d}" for d in set(str(n))}
    if n in P:p.add("prime")
    if round(n**.5)**2==n:p.add("square")
    if round(n**(1/3))**3==n:p.add("cube")
    for k in range(2,11):
        if n in {k**e for e in range(1,8)}:p.add(f"pow{k}")
    for k in range(3,13):
        if n%k==0:p.add(f"mult{k}")
    return p
PR={n:props(n) for n in range(1,101)}
from collections import Counter
cnt=Counter(f for n in range(1,101) for f in PR[n])
info={f:math.log(100/c) for f,c in cnt.items()}
X=[];y=[];N=[]
for r in rows:
    ex=[int(v) for v in r['number_set'].split(',')];t=int(r['target'])
    mag=sum(abs(t-x) for x in ex)/100
    lack=sum(sum(info[f] for f in PR[x]-PR[t]) for x in ex)
    extra=sum(sum(info[f] for f in PR[t]-PR[x]) for x in ex)
    X.append([mag,lack,extra]);y.append(int(r['rating']));N.append(len(ex))
X=np.array(X);y=np.array(y);N=np.array(N,float)
print(Counter(N), y.mean())
def nll(th,gamma_free=True):
    c0,lk,la,lb,g=th
    agg=N**(-g)
    eta=c0-agg*(np.exp(lk)*X[:,0]+np.exp(la)*X[:,1]+np.exp(lb)*X[:,2])
    p=1/(1+np.exp(-eta));p=np.clip(p,1e-9,1-1e-9)
    return -(y*np.log(p)+(1-y)*np.log(1-p)).sum()
for g0 in [0,1]:
    r=minimize(lambda th: nll(np.r_[th,g0]),np.zeros(4),method='Nelder-Mead',options={'maxiter':5000})
    print('gamma',g0,r.fun,r.x)
r=minimize(nll,np.zeros(5),method='Nelder-Mead',options={'maxiter':8000});print('free',r.fun,r.x)
