R+= [P,{n for n in range(1,101) if n%2==0},{n for n in range(1,101) if n%2},{n*n for n in range(1,11)},{n**3 for n in range(1,5)}]
Rm=np.zeros((len(R),101));
for i,s in enumerate(R):
    for n in s: Rm[i,n]=1
Rs=Rm.sum(1)
