def interval_sim(rho):
    S=np.zeros((101,101))
    for a in range(1,101):
        for b in range(a,101):
            S[a:b+1,a:b+1]+= (b-a+1)**(-rho)
    return S
def rule_sim(rho):
    w=Rs**(-rho); return (Rm*w[:,None]).T@Rm
ex=[[int(v) for v in r['number_set'].split(',')] for r in rows]; t=np.array([int(r['target']) for r in rows]); y=np.array([int(r['rating']) for r in rows])
