for i,e in enumerate(ex):
    idx[i,:len(e)]=e; M[i,:len(e)]=True
cache={}
def feats(rho):
    k=round(rho,3)
    if k not in cache:
        cache.clear(); SI=interval_sim(rho); SR=rule_sim(rho)
        cache[k]=(SI[t[:,None],idx], SR[t[:,None],idx])
    return cache[k]
def nll(th, agg):
    c0,c1,lw,rho=th
    SI,SR=feats(rho)
    s=SI+np.exp(lw)*SR
    ls=np.log(s+1e-12)
    a=(ls*M).sum(1)/M.sum(1) if agg=='geo' else np.where(M,ls,-1e9).max(1) if agg=='max' else np.where(M,ls,1e9).min(1)
    p=np.clip(1/(1+np.exp(-(c0+c1*a))),1e-9,1-1e-9)
    return -(y*np.log(p)+(1-y)*np.log(1-p)).sum()
for agg in ['geo','max','min']:
  best=None
  for rho in [0.5,1.0,1.5]:
    f=lambda th: nll(np.r_[th,rho],agg)
    r=minimize(f,np.array([0.,1.,0.]),method='Nelder-Mead',options={'maxiter':3000})
    print(agg,rho,round(r.fun,1),r.x)
